<?php
/**
 * Site redesign (Claude Design handoff): Home, Portfolio, Project, Process, Hosting and Contact rendered from
 * templates/redesign/*.html with assets/redesign/redesign.css + redesign.js, outside Elementor.
 *
 * Preview first: while Portfolio → Settings → "Redesign live" is off, only logged-in editors see it, after
 * opening any page with ?redesign=1 (?redesign=0 switches back). Logged-in pages are never cached, so
 * visitors keep seeing the current site until it goes live.
 *
 * The .html partials are generated by the converter from the design files; keep edits in the design and re-run.
 */
defined( 'ABSPATH' ) || exit;

const DWDR_COOKIE = 'dwd_redesign';

/** Copy written in the design for the two featured case studies; other projects use the fallback below. */
function dwdr_copy() {
	return array(
		'the-goods-vending' => array(
			'summary' => 'A premium vending company needed a website that felt as polished as the machines it places in offices and gyms. I designed and built a custom WordPress site around a full-screen hero video, a browsable product menu and a quote flow that turns visitors into placements.',
			'scope'   => 'Design, WordPress build, hero video, hosting',
			'h2a'     => 'Selling a premium service, not a snack machine',
			'p1'      => 'The Goods places high-end vending in offices, gyms and apartment communities. The old perception of vending is a dusty machine in a hallway, so the site had to do the opposite: open on motion, lead with the brands people recognize, and make the request process feel effortless.',
			'p2'      => 'The home page opens on a full-screen video of the machines in use, then moves through a dark, product-forward section ("Premium brands. Options for everyone."), the placement process and proof from existing locations. Every section ends with a single call to action: request a machine.',
			'h2b'     => 'Built to be run by the owner',
			'p3'      => 'The site runs on WordPress with Elementor, so the team can update the product menu, add locations and publish promotions without touching code. It is hosted and monitored on my managed hosting, with daily backups and same-day support.',
		),
		'finesse-by-witney' => array(
			'summary' => 'Launch website for Finesse, the fitness app by Dancing with the Stars pro Witney Carson. Built to drive App Store downloads with a video-led hero, program highlights and real App Store reviews.',
			'scope'   => 'Design, WordPress build, video, App Store funnels',
			'h2a'     => 'One job: get the app installed',
			'p1'      => 'Every section of the page points at the same action. The hero pairs the commercial with a direct "Find your program" button, the programs are shown as cards with level and length, and the reviews are pulled from the App Store.',
			'p2'      => 'The visual language borrows from the app itself: dark surfaces, a single pink accent and large uppercase headlines that match the brand.',
			'h2b'     => 'Fast on phones, where the audience is',
			'p3'      => 'Most visitors arrive from Instagram and TikTok on a phone, so the page is built mobile-first, with lazy-loaded video and a smart app banner at the top.',
		),
	);
}

/** True when this request should get the new design. */
function dwdr_on() {
	static $on = null;
	if ( null !== $on ) {
		return $on;
	}
	if ( is_admin() || wp_doing_ajax() || ( defined( 'REST_REQUEST' ) && REST_REQUEST ) ) {
		return $on = false;
	}
	if ( '1' === (string) get_option( 'dwdr_live', '0' ) ) {
		return $on = ! isset( $_GET['redesign'] ) || '0' !== $_GET['redesign']; // phpcs:ignore
	}
	if ( ! is_user_logged_in() || ! current_user_can( 'edit_posts' ) ) {
		return $on = false;
	}
	if ( isset( $_GET['redesign'] ) ) { // phpcs:ignore
		return $on = '1' === $_GET['redesign']; // phpcs:ignore
	}
	return $on = ! empty( $_COOKIE[ DWDR_COOKIE ] );
}

// ?redesign=1 / ?redesign=0 remembers the choice for the rest of the visit (editors only).
add_action( 'init', function () {
	if ( ! isset( $_GET['redesign'] ) || ! is_user_logged_in() || ! current_user_can( 'edit_posts' ) ) { // phpcs:ignore
		return;
	}
	$v = '1' === $_GET['redesign'] ? '1' : ''; // phpcs:ignore
	setcookie( DWDR_COOKIE, $v, $v ? time() + 30 * DAY_IN_SECONDS : time() - 3600, COOKIEPATH ?: '/', COOKIE_DOMAIN, is_ssl(), true );
	$_COOKIE[ DWDR_COOKIE ] = $v;
} );

/** Which redesigned page this request is, or ''. */
function dwdr_page() {
	if ( ! dwdr_on() ) {
		return '';
	}
	if ( is_front_page() ) {
		return 'home';
	}
	if ( is_singular( DWDP_CPT ) ) {
		return 'project';
	}
	if ( is_post_type_archive( DWDP_CPT ) || is_page( dwdp_base_slug() ) ) {
		return 'portfolio';
	}
	foreach ( array( 'process', 'hosting', 'contact' ) as $slug ) {
		if ( is_page( $slug ) ) {
			return $slug;
		}
	}
	return '';
}

add_filter( 'template_include', function ( $t ) {
	return dwdr_page() ? DWDP_DIR . 'templates/redesign/layout.php' : $t;
}, 100 );

/** Read a partial and fill its placeholders. {{ key }} values are escaped; {{{ key }}} are trusted HTML. */
function dwdr_render( $name, $vars = array() ) {
	$file = DWDP_DIR . 'templates/redesign/' . $name . '.html';
	if ( ! is_readable( $file ) ) {
		return '';
	}
	$html = (string) file_get_contents( $file ); // phpcs:ignore
	$html = preg_replace_callback( '/<!--if:(\w+)-->(.*?)<!--\/if:\1-->/s', function ( $m ) use ( $vars ) {
		return empty( $vars[ $m[1] ] ) ? '' : $m[2];
	}, $html );
	$html = preg_replace_callback( '/\{\{\{ ?([\w.]+) ?\}\}\}/', function ( $m ) use ( $vars ) {
		return isset( $vars[ $m[1] ] ) ? (string) $vars[ $m[1] ] : '';
	}, $html );
	$html = preg_replace_callback( '/\{\{ ?([\w.]+) ?\}\}/', function ( $m ) use ( $vars ) {
		return isset( $vars[ $m[1] ] ) ? esc_attr( (string) $vars[ $m[1] ] ) : '';
	}, $html );
	return strtr( $html, array(
		'%HOME%'  => untrailingslashit( home_url() ),
		'%MEDIA%' => DWDP_URL . 'assets/redesign/media/',
	) );
}

function dwdr_img_url( $id, $size = 'full' ) {
	$id = absint( $id );
	return $id ? (string) wp_get_attachment_image_url( $id, $size ) : '';
}

/** One project's values for the templates. */
function dwdr_project( $p ) {
	$wf = 'webflow' === dwdp_get( $p->ID, 'builder' );
	return array(
		'slug'     => $p->post_name,
		'name'     => get_the_title( $p ),
		'cat'      => (string) dwdp_get( $p->ID, 'industry' ),
		'desc'     => (string) dwdp_get( $p->ID, 'summary' ),
		'platform' => $wf ? 'Webflow' : 'WordPress',
		'cover'    => dwdr_img_url( dwdp_get( $p->ID, 'cover' ) ),
		'phone'    => dwdr_img_url( dwdp_get( $p->ID, 'mockup' ), 'large' ),
		'site'     => '1' === (string) dwdp_get( $p->ID, 'hide_link' ) ? '' : (string) dwdp_get( $p->ID, 'url' ),
		'href'     => get_permalink( $p ),
	);
}

/** The page body (between the nav and the footer for interior pages). */
function dwdr_body( $page ) {
	if ( 'portfolio' === $page ) {
		$list  = array_map( 'dwdr_project', dwdp_projects() );
		$spans = array( 12, 7, 5, 5, 7, 12, 6, 6, 7, 5, 12 );
		$cards = '';
		foreach ( $list as $i => $p ) {
			$span   = $spans[ $i % count( $spans ) ];
			$cards .= dwdr_render( 'portfolio-card', array(
				'p.href'         => $p['href'],
				'p.span'         => $span,
				'p.ratio'        => 12 === $span ? '21/9' : ( $span >= 7 ? '16/10' : '4/3' ),
				'p.cover'        => $p['cover'],
				'p.phone'        => $p['phone'],
				'p.alt'          => $p['name'] . ' website',
				'p.name'         => $p['name'],
				'p.cat'          => $p['cat'],
				'p.platform'     => $p['platform'],
				'p.platform_key' => strtolower( $p['platform'] ),
				'p.num'          => sprintf( '%02d', $i + 1 ),
			) );
		}
		$count = function ( $pl ) use ( $list ) {
			return count( array_filter( $list, function ( $p ) use ( $pl ) { return $p['platform'] === $pl; } ) );
		};
		$off = array( 'Bg' => 'transparent', 'Color' => '#fff', 'Border' => '#3A3A3A' );
		$on  = array( 'Bg' => '#13A6EE', 'Color' => '#fff', 'Border' => '#13A6EE' );
		$v   = array( 'cards' => $cards, 'countAll' => count( $list ), 'countWP' => $count( 'WordPress' ), 'countWF' => $count( 'Webflow' ), 'isAll' => 'true', 'isWP' => 'false', 'isWF' => 'false' );
		foreach ( array( 'all' => $on, 'wp' => $off, 'wf' => $off ) as $k => $set ) {
			foreach ( $set as $prop => $val ) {
				$v[ $k . $prop ] = $val;
			}
		}
		return dwdr_render( 'portfolio', $v );
	}
	if ( 'project' === $page ) {
		$all = dwdp_projects();
		$ids = wp_list_pluck( $all, 'ID' );
		$i   = array_search( get_queried_object_id(), array_map( 'intval', $ids ), true );
		$p   = dwdr_project( get_queried_object() );
		$nx  = $all ? dwdr_project( $all[ ( false === $i ? 0 : $i + 1 ) % count( $all ) ] ) : null;
		$c   = dwdr_copy();
		$cp  = isset( $c[ $p['slug'] ] ) ? $c[ $p['slug'] ] : array(
			'summary' => $p['desc'],
			'scope'   => 'Design, ' . $p['platform'] . ' build, launch, training',
			'h2a'     => 'Designed around the business',
			'p1'      => trim( $p['desc'] . ' Designed from scratch around the brand, the audience and the one thing visitors should do next.' ),
			'p2'      => 'The site was built page by page with the client approving each one before it went live, then tested on desktop, tablet and mobile before launch.',
			'h2b'     => 'Easy to keep current',
			'p3'      => 'Built on ' . $p['platform'] . ' so the owner can update text, images and pages after a one-on-one training session, with two months of support and a lifetime workmanship warranty included.',
		);
		return dwdr_render( 'project', array_merge( $p, $cp, array(
			'hasSite'   => '' !== $p['site'],
			'nextName'  => $nx ? $nx['name'] : '',
			'nextCat'   => $nx ? $nx['cat'] : '',
			'nextCover' => $nx ? $nx['cover'] : '',
			'nextHref'  => $nx ? $nx['href'] : home_url( '/portfolio/' ),
		) ) );
	}
	return dwdr_render( $page );
}

/* ---------- Assets: only the redesign's own CSS/JS on these pages ---------- */

add_action( 'wp_enqueue_scripts', function () {
	if ( ! dwdr_page() ) {
		return;
	}
	wp_enqueue_style( 'dwdr', DWDP_URL . 'assets/redesign/redesign-src.css', array(), DWDP_VERSION );
	wp_add_inline_style( 'dwdr', "@font-face{font-family:'Archivo';font-style:normal;font-weight:300 700;font-display:swap;src:url(" . DWDP_URL . "assets/fonts/archivo-latin.woff2) format('woff2');unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD}"
		. '.admin-bar #dw-nav,.admin-bar #dw-menu>div{top:32px!important}@media(max-width:782px){.admin-bar #dw-nav,.admin-bar #dw-menu>div{top:46px!important}}'
		. '@media(max-width:600px){#dw-hero-cta>#dw-hero-trust{flex-direction:row!important;flex-wrap:wrap;align-items:center!important;gap:6px 10px!important}}' // the design's phone rule stacked the trust strip too
		. '.dwr-form[data-sent="1"] .dwr-fields{display:none}.dwr-note{font-size:14px;color:#F27A7A;min-height:1em}' );
	wp_enqueue_script( 'dwdr', DWDP_URL . 'assets/redesign/redesign.js', array(), DWDP_VERSION, true );
	// Theme, Elementor and the old page scripts have nothing to do on these pages.
	foreach ( wp_scripts()->queue as $h ) {
		if ( preg_match( '/^(elementor|hello|swiper|dwdp-front|dwdp-onboarding|e-sticky|imagesloaded|jquery)/', $h ) ) {
			wp_dequeue_script( $h );
		}
	}
}, 9999 );

add_filter( 'sgo_css_combine_exclude', function ( $ex ) {
	$ex[] = 'dwdr';
	return $ex;
} );
add_filter( 'sgo_js_minify_exclude', function ( $ex ) {
	$ex[] = 'dwdr';
	return $ex;
} );

/**
 * wp_head for these pages, minus every other stylesheet and inline style (theme, Elementor, the old page
 * styles) and the old font/hero preloads. SEO tags, schema and tracking stay.
 */
function dwdr_head() {
	ob_start();
	wp_head();
	$h = (string) ob_get_clean();
	$keep_style = '/id=["\'](dwdr|admin-bar|dashicons|query-monitor)/';
	$h = preg_replace_callback( '#<link\b[^>]*rel=["\']stylesheet["\'][^>]*>\s*#i', function ( $m ) use ( $keep_style ) {
		return preg_match( $keep_style, $m[0] ) ? $m[0] : '';
	}, $h );
	$h = preg_replace_callback( '#<style\b[^>]*>.*?</style>\s*#is', function ( $m ) use ( $keep_style ) {
		return preg_match( $keep_style, $m[0] ) || false !== strpos( $m[0], 'img:is(' ) ? $m[0] : '';
	}, $h );
	$h = preg_replace( '#<link\b[^>]*rel=["\']preload["\'][^>]*>\s*#i', '', $h );
	$h = preg_replace( '#<link\b[^>]*fonts\.(googleapis|gstatic)\.com[^>]*>\s*#i', '', $h );
	echo '<link rel="preload" href="' . esc_url( DWDP_URL . 'assets/fonts/archivo-latin.woff2' ) . '" as="font" type="font/woff2" crossorigin>' . "\n";
	echo $h; // phpcs:ignore
}

/* ---------- Settings: the switch that makes it live ---------- */

add_action( 'admin_init', function () {
	register_setting( 'dwdr', 'dwdr_live', array( 'type' => 'string', 'sanitize_callback' => function ( $v ) { return '1' === (string) $v ? '1' : '0'; } ) );
} );
